-- Apply ONLY to a new, isolated Supabase staging project.
begin;
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 120),created_at timestamptz not null default now());
create table public.memberships(organization_id uuid references public.organizations on delete cascade,user_id uuid references auth.users on delete cascade,primary key(organization_id,user_id));
create table public.jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,title text not null check(length(trim(title)) between 1 and 120),location text not null check(length(trim(location)) between 1 and 120),description text not null check(length(trim(description)) between 1 and 12000),type text not null check(type in ('full-time','part-time','contract')),status text not null default 'open' check(status in ('open','closed')),created_at timestamptz not null default now());
create table public.applications(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.jobs,candidate_id uuid not null references auth.users on delete cascade,cover_letter text not null check(length(trim(cover_letter)) between 1 and 5000),status text not null default 'submitted' check(status in ('submitted','reviewing','interview','offer','hired','rejected')),created_at timestamptz not null default now(),unique(job_id,candidate_id));
create index jobs_org_idx on public.jobs(organization_id);
create index applications_candidate_idx on public.applications(candidate_id);
create index memberships_user_idx on public.memberships(user_id);
create function public.is_member(org uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships where organization_id=org and user_id=auth.uid())$$;
create function public.owns_job(job uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.jobs j join public.memberships m on m.organization_id=j.organization_id where j.id=job and m.user_id=auth.uid())$$;
create function public.applied_to(job uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.applications where job_id=job and candidate_id=auth.uid())$$;
create function public.create_organization(org_name text) returns uuid language plpgsql security definer set search_path='' as $$declare org_id uuid;begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if exists(select 1 from public.memberships where user_id=auth.uid()) then raise exception 'An organization already exists'; end if;
 insert into public.organizations(name) values(trim(org_name)) returning id into org_id;
 insert into public.memberships values(org_id,auth.uid());return org_id;end$$;
alter table public.organizations enable row level security;
alter table public.memberships enable row level security;
alter table public.jobs enable row level security;
alter table public.applications enable row level security;
create policy org_read on public.organizations for select using(true);
create policy membership_read on public.memberships for select to authenticated using(user_id=auth.uid());
create policy jobs_read on public.jobs for select using(status='open' or public.is_member(organization_id) or public.applied_to(id));
create policy jobs_insert on public.jobs for insert to authenticated with check(public.is_member(organization_id));
create policy jobs_update on public.jobs for update to authenticated using(public.is_member(organization_id)) with check(public.is_member(organization_id));
create policy applications_read on public.applications for select to authenticated using(candidate_id=auth.uid() or public.owns_job(job_id));
create policy applications_insert on public.applications for insert to authenticated with check(candidate_id=auth.uid() and status='submitted' and exists(select 1 from public.jobs where id=job_id and status='open') and not public.owns_job(job_id));
create policy applications_update on public.applications for update to authenticated using(public.owns_job(job_id)) with check(public.owns_job(job_id));
revoke all on public.organizations,public.memberships,public.jobs,public.applications from anon,authenticated;
grant select on public.organizations,public.jobs to anon,authenticated;
grant select on public.memberships,public.applications to authenticated;
grant insert on public.jobs to authenticated;
grant update(status) on public.jobs to authenticated;
grant insert(job_id,candidate_id,cover_letter) on public.applications to authenticated;
grant update(status) on public.applications to authenticated;
revoke all on function public.create_organization(text) from public,anon;
grant execute on function public.create_organization(text) to authenticated;
revoke all on function public.is_member(uuid),public.owns_job(uuid),public.applied_to(uuid) from public;
grant execute on function public.is_member(uuid),public.owns_job(uuid),public.applied_to(uuid) to anon,authenticated;
commit;
